SELECT lr.* FROM leave_request lr
INNER JOIN student s ON lr.student_id = s.id
WHERE lr.counselor_id = #{counselorId}

    AND s.class_id = #{classId}


    AND s.student_no = #{studentNo}


    AND lr.status = #{status}


    AND lr.leave_type = #{leaveType}


    AND lr.leave_date >= #{dateFrom}


    AND lr.leave_date <= #{dateTo}

ORDER BY lr.id DESC

    LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM leave_request lr
INNER JOIN student s ON lr.student_id = s.id
WHERE lr.counselor_id = #{counselorId}

    AND s.class_id = #{classId}


    AND s.student_no = #{studentNo}


    AND lr.status = #{status}


    AND lr.leave_type = #{leaveType}


    AND lr.leave_date >= #{dateFrom}


    AND lr.leave_date <= #{dateTo}

SELECT * FROM leave_request
WHERE teacher_id = #{teacherId}

    AND course_id = #{courseId}


    AND status = #{status}


    AND leave_date >= #{dateFrom}


    AND leave_date <= #{dateTo}

ORDER BY leave_date DESC

    LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM leave_request
WHERE teacher_id = #{teacherId}

    AND course_id = #{courseId}


    AND status = #{status}


    AND leave_date >= #{dateFrom}


    AND leave_date <= #{dateTo}

SELECT
    s.student_no,
    s.name AS student_name,
    COUNT(*) AS leave_count
FROM leave_request lr
INNER JOIN student s ON lr.student_id = s.id
WHERE lr.counselor_id = #{counselorId}
  AND lr.status = 'APPROVED'

    AND s.class_id = #{classId}


    AND lr.leave_date >= #{dateFrom}


    AND lr.leave_date <= #{dateTo}

GROUP BY s.id, s.student_no, s.name
ORDER BY leave_count DESC

SELECT
    s.student_no,
    s.name AS student_name,
    COUNT(*) AS leave_count
FROM leave_request lr
INNER JOIN student s ON lr.student_id = s.id
WHERE lr.teacher_id = #{teacherId}
  AND lr.status = 'APPROVED'

    AND lr.course_id = #{courseId}


    AND lr.leave_date >= #{dateFrom}


    AND lr.leave_date <= #{dateTo}

GROUP BY s.id, s.student_no, s.name
ORDER BY leave_count DESC

SELECT COUNT(*) FROM leave_request
WHERE student_id = #{studentId}
  AND course_id = #{courseId}
  AND leave_date = #{leaveDate}

